/**
 * Notion Node - Version 2.2
 * Discriminator: resource=block, operation=getAll
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Get many child blocks */
export type NotionV22BlockGetAllParams = {
  resource: 'block';
  operation: 'getAll';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * The Notion Block to get all children from, when using 'By URL' mode make sure to use the URL of the block itself, you can find it in block parameters in Notion under 'Copy link to block'
 * @default {"mode":"url","value":""}
 */
    blockId?: { __rl: true; mode: 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
/**
 * Also Fetch Nested Blocks
 * @default false
 */
    fetchNestedBlocks?: boolean | Expression<boolean>;
/**
 * Simplify Output
 * @builderHint When true, adds root_id and removes created_time, last_edited_time, and created_by. Child page and child database titles become content. A block-type text array becomes content by joining its plain_text values. A rich_text-only block keeps its nested data, so content is not guaranteed. When false, keeps the native block fields. Match downstream expressions and verification output fixtures to the block type and output mode.
 * @default true
 */
    simplifyOutput?: boolean | Expression<boolean>;
};

export type NotionV22BlockGetAllOutput = {
  archived?: boolean;
  content?: string;
  has_children?: boolean;
  id?: string;
  in_trash?: boolean;
  last_edited_by?: {
    id?: string;
    object?: string;
  };
  object?: string;
  parent?: {
    page_id?: string;
    type?: string;
  };
  parent_id?: string;
  root_id?: string;
  type?: string;
};

export type NotionV22BlockGetAllNode = {
  type: 'n8n-nodes-base.notion';
  version: 2.2;
  config: NodeConfig<NotionV22BlockGetAllParams> & { credentials?: Credentials };
  output?: Items<NotionV22BlockGetAllOutput>;
};